{"argv":["python3","-c","import pathlib,csv,hashlib,collections,json
files=sorted(p.name for p in pathlib.Path('/task').glob('shard_*.csv'))
rows=[]
shas={}
for n in files:
    p=pathlib.Path('/task')/n
    data=p.read_bytes()
    shas[n]=hashlib.sha256(data).hexdigest()
    for i,r in enumerate(csv.DictReader(data.decode().splitlines())):
        r['_file']=n; r['_line']=i+2; rows.append(r)
print('files',len(files),'rows',len(rows))
print('statuses',collections.Counter(r['status'] for r in rows))
by=collections.defaultdict(list)
for r in rows: by[r['record_id']].append(r)
dup={k:v for k,v in by.items() if len(v)>1}
print('unique_ids',len(by),'dup_ids',len(dup))
conflict=0
for k,v in sorted(dup.items()):
    sig={(r['amount_cents'],r['status']) for r in v}
    if len(sig)>1:
        conflict+=1
        print('CONFLICT',k,[(r['_file'],r['amount_cents'],r['status']) for r in v])
print('conflicts',conflict)
print('dup_file_counts',collections.Counter(len(v) for v in dup.values()))
print('dup_sample',[(k,[(r['_file'],r['amount_cents'],r['status']) for r in v]) for k,v in sorted(dup.items())[:5]])
print('fields',{tuple(sorted(set(r.keys())-{'_file','_line'})) for r in rows})
print('amount_nonint',[r for r in rows if not r['amount_cents'].lstrip('-').isdigit()][:5])
print('shas',json.dumps(shas,indent=0))"]}

